CREATE TABLE domox.AttributeCdd (ID BIGINT NOT NULL, CANDIDATENAME VARCHAR(255) NOT NULL, CANDIDATETYPE VARCHAR(255) NOT NULL, HOPDEPTH INTEGER NOT NULL, TYPE VARCHAR(255) NOT NULL, VERSION INTEGER NOT NULL, CLASSCDD_ID BIGINT NOT NULL, DOMAINMODEL_ID BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.ClassCdd (ID BIGINT NOT NULL, CANDIDATENAME VARCHAR(255) NOT NULL, CANDIDATETYPE VARCHAR(255) NOT NULL, CLASSTYPE INTEGER, HOPDEPTH INTEGER NOT NULL, VERSION INTEGER NOT NULL, DOMAINMODEL_ID BIGINT NOT NULL, subdomain_id BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.CollaboratorCdd (ID BIGINT NOT NULL, CANDIDATENAME VARCHAR(255) NOT NULL, CANDIDATETYPE VARCHAR(255) NOT NULL, HOPDEPTH INTEGER NOT NULL, SOURCECARDINALITY VARCHAR(255) NOT NULL, TARGETCARDINALITY VARCHAR(255) NOT NULL, TYPE INTEGER NOT NULL, VERSION INTEGER NOT NULL, CLASSCDD_ID BIGINT NOT NULL, DOMAINMODEL_ID BIGINT, SOURCE_ID BIGINT, TARGET_ID BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.DomainModel (ID BIGINT NOT NULL, VERSION INTEGER NOT NULL, PRIMARY KEY (ID))
CREATE TABLE domox.ResponsibilityCdd (ID BIGINT NOT NULL, CANDIDATENAME VARCHAR(255) NOT NULL, CANDIDATETYPE VARCHAR(255) NOT NULL, HOPDEPTH INTEGER NOT NULL, OUTPUTTYPE VARCHAR(255) NOT NULL, VERSION INTEGER NOT NULL, CLASSCDD_ID BIGINT, DOMAINMODEL_ID BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.ResponsibilityParameter (ID BIGINT NOT NULL, CANDIDATENAME VARCHAR(255) NOT NULL, CANDIDATETYPE VARCHAR(255) NOT NULL, HOPDEPTH INTEGER NOT NULL, TYPE VARCHAR(255) NOT NULL, VERSION INTEGER NOT NULL, responsibilitycdd_id BIGINT NOT NULL, PRIMARY KEY (ID))
CREATE TABLE domox.Review (ID BIGINT NOT NULL, CREATEDAT TIMESTAMP NOT NULL, RATIONALE VARCHAR(255), STATUS VARCHAR(255), UPDATEDAT TIMESTAMP, username VARCHAR(255) NOT NULL, VERSION INTEGER NOT NULL, CANDIDATE_ID BIGINT NOT NULL, PRIMARY KEY (ID))
CREATE TABLE domox.SubDomain (ID BIGINT NOT NULL, CLASSIFICATION VARCHAR(255) NOT NULL, NAME VARCHAR(255) NOT NULL, VERSION INTEGER NOT NULL, PRIMARY KEY (ID))
CREATE TABLE domox.Sentence (ID BIGINT NOT NULL, TEXT TEXT, VERSION INTEGER NOT NULL, diagram_bytes BYTEA, diagram_mimeType VARCHAR(255), diagram_name TEXT, documentId BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.TypedDependency (ID BIGINT NOT NULL, DEPENDENTGLOSS VARCHAR(255), DEPENDENTINDEX INTEGER NOT NULL, DEPENDENTLEMMA VARCHAR(255), DEPENDENTPOS VARCHAR(255), GOVERNORGLOSS VARCHAR(255), GOVERNORINDEX INTEGER NOT NULL, GOVERNORLEMMA VARCHAR(255), GOVERNORPOS VARCHAR(255), TYPE INTEGER NOT NULL, VERSION INTEGER NOT NULL, sentence_id BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.Author (ID BIGINT NOT NULL, EMAIL VARCHAR(255), FIRSTNAME VARCHAR(255), LASTNAME VARCHAR(255), MIDDLEINITIAL VARCHAR(255), VERSION INTEGER NOT NULL, PRIMARY KEY (ID))
CREATE TABLE domox.Corpus (ID BIGINT NOT NULL, ANALYZEDAT TIMESTAMP NOT NULL, TITLE VARCHAR(255), VERSION INTEGER NOT NULL, domain_model_id BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.Document (ID BIGINT NOT NULL, CREATEDAT TIMESTAMP NOT NULL, DOCVERSION VARCHAR(255) NOT NULL, FILENAME VARCHAR(255), TITLE VARCHAR(255) NOT NULL, UPDATEDAT TIMESTAMP, URL VARCHAR(255), VERSION INTEGER NOT NULL, CHARS TEXT NOT NULL, MIMETYPE VARCHAR(255) NOT NULL, NAME VARCHAR(255) NOT NULL, corpus_id BIGINT, domain_model_id BIGINT, PRIMARY KEY (ID))
CREATE TABLE domox.RuleMatch (ID BIGINT NOT NULL, CANDIDATENAME VARCHAR(255) NOT NULL, CANDIDATETYPE VARCHAR(255) NOT NULL, DESCRIPTION VARCHAR(255), RELATEDCANDIDATENAME VARCHAR(255), RELATEDCANDIDATETYPE VARCHAR(255), RULECLASSNAME VARCHAR(255) NOT NULL, VERSION INTEGER NOT NULL, typed_dependency_id BIGINT NOT NULL, PRIMARY KEY (ID))
